class Solution:
    def generateSchedule(self, n: int) -> List[List[int]]:
        if n <= 3:
            return []
        arr = list(range(n))
        if n % 2:
            arr.append(None)
        m = len(arr)
        rounds = []
        for rd in range(m - 1):
            cur = []
            for i in range(m // 2):
                a, b = arr[i], arr[m - 1 - i]
                if a is not None and b is not None:
                    cur.append([a, b] if (i + rd) % 2 else [b, a])
            rounds.append(cur)
            arr = [arr[0], arr[-1]] + arr[1:-1]
        sched = []
        for half in range(2):
            for cur in rounds:
                cur = [list(x) for x in cur]
                if half:
                    cur = [[b, a] for a, b in cur]
                if sched and set(sched[-1]) & set(cur[0]) and len(cur) > 1:
                    cur[0], cur[1] = cur[1], cur[0]
                sched.extend(cur)
        return sched

