class Solution {
public:
    vector<vector<int>> generateSchedule(int n) {
        if (n <= 3) return {};
        vector<int> arr(n);
        iota(arr.begin(), arr.end(), 0);
        bool odd = n % 2;
        if (odd) arr.push_back(-1);
        int m = arr.size();
        vector<vector<vector<int>>> rounds;
        for (int rd = 0; rd < m - 1; rd++) {
            vector<vector<int>> cur;
            for (int i = 0; i < m / 2; i++) {
                int a = arr[i], b = arr[m - 1 - i];
                if (a >= 0 && b >= 0)
                    cur.push_back(((i + rd) % 2) ? vector<int>{a, b} : vector<int>{b, a});
            }
            rounds.push_back(cur);
            vector<int> nxt = {arr[0], arr.back()};
            for (int i = 1; i + 1 < m; i++) nxt.push_back(arr[i]);
            arr = nxt;
        }
        vector<vector<int>> sched;
        auto emit = [&](vector<vector<int>> cur) {
            if (!sched.empty() && !(sched.back()[0] == cur[0][0] || sched.back()[0] == cur[0][1] ||
                                    sched.back()[1] == cur[0][0] || sched.back()[1] == cur[0][1])) {
                sched.push_back(cur[0]);
            } else if (!sched.empty() && cur.size() > 1) {
                swap(cur[0], cur[1]);
                sched.push_back(cur[0]);
            } else {
                sched.push_back(cur[0]);
            }
            for (size_t i = 1; i < cur.size(); i++) sched.push_back(cur[i]);
        };
        for (auto &r : rounds) emit(r);
        for (auto &r : rounds) {
            vector<vector<int>> rev;
            for (auto &mt : r) rev.push_back({mt[1], mt[0]});
            emit(rev);
        }
        return sched;
    }
};

