class Solution {
    public int[][] generateSchedule(int n) {
        if (n <= 3) return new int[0][];
        List<Integer> arr = new ArrayList<>();
        for (int i = 0; i < n; i++) arr.add(i);
        if (n % 2 == 1) arr.add(-1);
        int m = arr.size();
        List<List<int[]>> rounds = new ArrayList<>();
        for (int rd = 0; rd < m - 1; rd++) {
            List<int[]> cur = new ArrayList<>();
            for (int i = 0; i < m / 2; i++) {
                int a = arr.get(i), b = arr.get(m - 1 - i);
                if (a >= 0 && b >= 0)
                    cur.add(((i + rd) % 2 == 1) ? new int[]{a, b} : new int[]{b, a});
            }
            rounds.add(cur);
            List<Integer> nxt = new ArrayList<>();
            nxt.add(arr.get(0)); nxt.add(arr.get(m - 1));
            for (int i = 1; i + 1 < m; i++) nxt.add(arr.get(i));
            arr = nxt;
        }
        List<int[]> sched = new ArrayList<>();
        for (int half = 0; half < 2; half++) {
            for (List<int[]> r : rounds) {
                List<int[]> cur = new ArrayList<>();
                for (int[] mt : r) cur.add(half == 1 ? new int[]{mt[1], mt[0]} : mt.clone());
                if (!sched.isEmpty() && clashes(sched.get(sched.size() - 1), cur.get(0)) && cur.size() > 1) {
                    int[] t = cur.get(0); cur.set(0, cur.get(1)); cur.set(1, t);
                }
                sched.addAll(cur);
            }
        }
        return sched.toArray(new int[0][]);
    }
    private boolean clashes(int[] a, int[] b) {
        return a[0] == b[0] || a[0] == b[1] || a[1] == b[0] || a[1] == b[1];
    }
}

