var generateSchedule = function(n) {
    if (n <= 3) return [];
    let arr = [...Array(n).keys()];
    if (n % 2) arr.push(null);
    const m = arr.length, rounds = [];
    for (let rd = 0; rd < m - 1; rd++) {
        const cur = [];
        for (let i = 0; i < m / 2; i++) {
            const a = arr[i], b = arr[m - 1 - i];
            if (a !== null && b !== null)
                cur.push((i + rd) % 2 ? [a, b] : [b, a]);
        }
        rounds.push(cur);
        arr = [arr[0], arr[m - 1], ...arr.slice(1, m - 1)];
    }
    const sched = [];
    const clash = (a, b) => a[0] === b[0] || a[0] === b[1] || a[1] === b[0] || a[1] === b[1];
    for (let half = 0; half < 2; half++) {
        for (let r of rounds) {
            const cur = r.map(mt => half ? [mt[1], mt[0]] : [...mt]);
            if (sched.length && clash(sched[sched.length - 1], cur[0]) && cur.length > 1) {
                [cur[0], cur[1]] = [cur[1], cur[0]];
            }
            sched.push(...cur);
        }
    }
    return sched;
};
